import { test, expect } from '@playwright/test';

test.describe('Success Toast Notification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display success toast notification after saving a record', async ({ page }) => {
    await page.fill(getByLabel('Record Name'), 'Test Record'); // Replace with actual label
    await page.click(getByRole('button', { name: 'Save' })); // Replace with actual button name

    const toast = await page.getByRole('alert', { name: 'Success' }); // Replace with actual alert role and name
    await expect(toast).toBeVisible();
    await expect(toast).toHaveText('Record saved successfully!'); // Replace with actual success message
  });

  test('should not display success toast notification if save fails', async ({ page }) => {
    await page.fill(getByLabel('Record Name'), ''); // Simulate invalid input
    await page.click(getByRole('button', { name: 'Save' })); // Replace with actual button name

    const toast = page.getByRole('alert', { name: 'Success' }); // Replace with actual alert role and name
    await expect(toast).not.toBeVisible();
  });
});
